Object.assign(text.en,{height_cm:'Height, cm',weight_kg:'Body weight, kg',automatic:'Calculated automatically',bmihelp:'Calculated from height and weight; weight also informs stimulation dosing.',height_weight:'Height and weight',interpretation:'Interpretation',anthropometry:'Height and weight',cm:'cm',kg:'kg',deltafirst:'First stimulation cycle with follitropin delta',delta:'Follitropin delta',deltaunit:'micrograms/day',deltamissing:'Enter weight and confirm the first cycle with this medicine. Subsequent cycles require the previous stimulation response.',deltacheck:'The nomogram requires AMH measured within 12 months using ELECSYS AMH Plus, ACCESS AMH Advanced or LUMIPULSE G AMH. Rounded to the pen scale; not a dose for other gonadotropins.',evidencetitle:'Calculation basis and recommendations',cluster:'Group of comparable cycles',clusterlead:'Predominant group',clustershare:'Scenario share',clusternote:'Scenario membership across model clusters, not a treatment outcome probability.',pregtarget:'Target pregnancy probability across transfers',bankconfidence:'Confidence of obtaining the required embryos',mii_required:'Required mature oocytes (MII)',euploid_required:'Required euploid embryos',banknote:'First calculate embryos needed for the target pregnancy probability across successive transfers. The Esteves model then determines MII needed to obtain those embryos with the selected confidence. This preserves the Digital Twin assumptions of a constant pregnancy probability and independent transfers. The per-transfer estimate is a proxy; neither threshold alone is the overall pregnancy probability after banking.',bankcurve:'Probability of obtaining the required euploid embryos',banklimit:'More than 200 MII within this model',layeroutputs:'Individual layer outputs',csdicounts:'Blastocyst counts: median and 95% interval',cohortgraph:'Graph of comparable cycles',graphnote:'All training nodes and the patient in a two-dimensional PCA projection. Lines show her nearest neighbours. Projected distances do not replace OOD assessment.',patientnode:'Current patient',cohortnode:'Training cycle',graphmissing:'Graph coordinates are unavailable for this record. Run a new calculation.',resetview:'Reset view',oodscope:'Assesses age, AFC and oocyte, MII, 2PN and blastocyst counts. AMH and BMI are not assessed here.',oodinside:'No departure from the reference cohort was detected in the assessed features.',reliabilitysettings:'Reliability index thresholds',moderate:'Moderate from',high:'High from',reliabilityhelp:'Thresholds change the index level label, not pregnancy probabilities, intervals or OOD assessment.',thresholdsaved:'Thresholds saved',layerinterval:'95% scenario spread',modelrange:'Model uncertainty range',modelrangenote:'Combines uncertainty about cycle results not yet known and the models’ own uncertainty; it narrows as observations arrive. Disagreement beyond that own uncertainty widens it. Not a confidence interval with validated coverage.',range_cycle:'From unknown cycle results',range_models:'From model uncertainty and disagreement',transfershare:'Cycle scenarios with an embryo for transfer',scenario_all:'No PGT-A: every blastocyst is transferable, good quality first',scenario_pgt:'PGT-A: only euploid embryos are transferred',densitylabel:'Probability and model uncertainty range',modelindex:'Reliability index',level_low:'Low',level_moderate:'Moderate',level_high:'High'});
function oodNotice(r){if(!r.ood_assessment?.available)return `<div class="note">${t('ood_missing')}</div>`;return `<div class="${r.fusion?.ood_final?'note':'assessment-line'}">${t(r.fusion?.ood_final?'ood':'oodinside')} <small>${t('oodscope')}</small></div>`}
function probabilityCard(r){
 const f=r.fusion||{},p=r.patient||{},closed=r.clinical_summary?r.clinical_summary.no_transfer_confirmed:(['okk','mii','pn2','blasts'].some(k=>p['known_'+k]===0)||p.known_euploid===0),prob=closed?0:r.headline;
 const part=sd=>{if(sd==null||prob==null||!(prob>0&&prob<1))return null;const l=Math.log(prob/(1-prob));return [1/(1+Math.exp(-(l-1.96*sd))),1/(1+Math.exp(-(l+1.96*sd)))]};
 const parts=mode!=='research'||closed?'':[['range_cycle',part(f.range_scenario_sd)],['range_models',part(f.range_model_sd)]].filter(v=>v[1]).map(([k,v])=>`<div class="metric-row readout-row"><span>${t(k)}</span><strong>${pct(v[0])} – ${pct(v[1])}</strong></div>`).join('');
 const plan=p.n_transfers_planned;
 const extra=closed?'':parts+`<div class="metric-row readout-row"><span>${t('cyclep')}${plan?' · '+esc(t('plannedsuffix').replace('{n}',plan)):''}</span><strong>${pct(r.cycle_probability)}</strong></div>${r.transfer_possible_share==null?'':`<div class="metric-row readout-row"><span>${t('transfershare')}</span><strong>${pct(r.transfer_possible_share)}</strong></div>`}`;
 return `<section class="headline-card probability-card"><div class="probability-plot">${probabilityPlot(prob,closed?0:f.ci_low,closed?0:f.ci_high)}</div><div class="probability-readout"><div class="eyebrow">${t('current')}</div><h3>${t(closed?'current_cycle_headline':'headline')}</h3><div class="big-number">${pct(prob)}</div><p class="metric-caption">${closed?t('no_transfer_recorded'):t('modelrange')+' · '+pct(f.ci_low)+' – '+pct(f.ci_high)}</p>${closed?'':`<small class="hint">${t('modelrangenote')}</small>`}${r.center_calibration?.enabled?`<small>${t(r.center_calibration.applicable?'center_adjusted':'center_not_applicable')}</small>`:''}${extra}${r.transfer_scenario?`<small class="hint">${t(r.transfer_scenario==='pgt'?'scenario_pgt':'scenario_all')}</small>`:''}</div></section>`;
}
function probabilityPlot(p,lo,hi){
 const x=v=>32+v*536,y0=214;
 if(p==null)return '';
 if(!(0<p&&p<1&&lo>0&&hi<1&&hi>lo))return `<svg class="plot-svg" viewBox="0 0 600 260" role="img" aria-label="${t('densitylabel')}"><line x1="32" y1="214" x2="568" y2="214" class="chart-axis"/><circle cx="${x(p)}" cy="214" r="7" class="chart-dot"/><text x="${Math.max(35,Math.min(560,x(p)))}" y="194" text-anchor="middle" class="chart-value">${pct(p)}</text></svg>`;
 const logit=v=>Math.log(v/(1-v)),mu=logit(p),sd=(logit(hi)-logit(lo))/3.92;
 const points=Array.from({length:199},(_,i)=>{const v=(i+1)/200;return [v,Math.exp(-.5*((logit(v)-mu)/sd)**2)/(v*(1-v)*sd)]}),max=Math.max(...points.map(v=>v[1]));
 const line=points.map(([v,d])=>`${x(v).toFixed(2)},${(y0-170*d/max).toFixed(2)}`).join(' '),area=`M32,214 L${line.replace(/ /g,' L')} L568,214 Z`;
 return `<svg class="plot-svg" viewBox="0 0 600 260" role="img" aria-label="${t('densitylabel')}"><defs><linearGradient id="prob-fill" x1="0" y1="0" x2="0" y2="1"><stop style="stop-color:var(--chart)" stop-opacity=".55"/><stop offset="1" style="stop-color:var(--chart)" stop-opacity=".04"/></linearGradient><clipPath id="prob-ci"><rect x="${x(lo)}" y="0" width="${x(hi)-x(lo)}" height="214"/></clipPath></defs><path d="${area}" fill="url(#prob-fill)"/><path d="${area}" class="chart-bar" opacity=".35" clip-path="url(#prob-ci)"/><polyline points="${line}" class="chart-line" stroke-width="2.5"/><line x1="${x(p)}" x2="${x(p)}" y1="26" y2="214" class="chart-marker" stroke-dasharray="4 4"/><line x1="32" x2="568" y1="214" y2="214" class="chart-axis"/>${[0,.25,.5,.75,1].map(v=>`<text x="${x(v)}" y="240" text-anchor="middle">${Math.round(v*100)}%</text>`).join('')}</svg>`;
}
function layerCards(r){const n=r.technical?.neural||{},c=r.technical?.csdi||{},g=r.technical?.gnn||{},f=r.fusion||{};
 const item=(title,p,ci)=>`<section class="layer-card"><h3>${title}</h3><strong>${pct(p)}</strong>${ci?`<small>${t('layerinterval')}: ${pct(ci[0])} – ${pct(ci[1])}</small>`:''}</section>`;
 const counts=c.PI_95_counts||{},rows=[['blasts','blast_total_median','Число Bl'],['good','good_blast_median','Число Bl хор.кач-ва']],level=f.reliability>=reliabilityConfig.high?'high':f.reliability>=reliabilityConfig.moderate?'moderate':'low';
 return `<aside class="layer-stack">${item('KAT · L3',n.base_prob_mean??f.raw_experts?.KAT,n.base_prob_ci)}${item('CSDI · L5',c.P_pregnancy,c.CI_95)}${r.csdi_applicability?.used_in_fusion===false?`<small class="note">${esc(r.csdi_note?.[lang]||t('csdi_excluded'))}</small>`:''}<section class="layer-card"><h3>${t('csdicounts')}</h3>${rows.map(([label,key,cnt])=>`<div class="metric-row"><span>${t(label)}</span><span class="value-group"><strong>${num(c[key])}</strong><small>${counts[cnt]?counts[cnt].map(num).join(' – '):'—'}</small></span></div>`).join('')}</section>${item('GAT · L6',g.gnn_prob)}<section class="layer-card"><h3>${t('modelindex')}</h3><strong>${f.reliability??'—'} / 100</strong>${f.reliability==null?'':`<small>${t('level_'+level)}</small>`}</section></aside>`;
}
function clusterPanel(r){const c=r.technical?.cluster;if(!c)return '';return `<section class="panel"><h2>${t('cluster')}${mode==='research'?' · L4':''}</h2><div class="metric-row"><span>${t('clusterlead')}</span><strong>${t('cluster_'+c.dominant_cluster)}</strong></div><div class="cluster-bars">${Object.entries(c.cluster_probs||{}).map(([key,p])=>`<div><span>${t('cluster_'+key)}</span><div class="bar"><span style="width:${p*100}%"></span></div><strong>${pct(p)}</strong></div>`).join('')}</div><p class="hint">${t('clusternote')}</p></section>`}
function bankingPanel(){const b=result.banking_plan;return `<section class="panel"><h2>${t('banking')}</h2><div class="grid2"><label class="field">${t('pregtarget')} <output id="preg-target-label">${Math.round((b?.target??.7)*100)}%</output><input id="preg-target" type="range" min="1" max="99" value="${Math.round((b?.target??.7)*100)}"></label><label class="field">${t('bankconfidence')} <output id="bank-confidence-label">${Math.round((b?.confidence??.8)*100)}%</output><input id="bank-confidence" type="range" min="1" max="99" value="${Math.round((b?.confidence??.8)*100)}"></label></div><div id="banking-output">${b?bankingHTML(b):''}</div><p class="hint">${t('banknote')}</p></section>`}
function bankingHTML(b){if(!b.available)return `<p>${t('unavailable')}</p>`;const v=b.curve,max=Math.max(...v.mii),x=n=>50+n/max*680,y=p=>180-p*145,n=b.mii_needed;return `<svg viewBox="0 0 780 235" class="chart" aria-label="${t('bankcurve')}"><line x1="50" y1="${y(b.confidence)}" x2="730" y2="${y(b.confidence)}" stroke="#ad8a57" stroke-dasharray="5 4"/><line x1="50" y1="180" x2="730" y2="180" class="chart-axis"/><polyline points="${v.mii.map((n,i)=>`${x(n)},${y(v.probability[i])}`).join(' ')}" class="chart-line" stroke-width="3"/>${n==null?'':`<line x1="${x(n)}" x2="${x(n)}" y1="${y(b.confidence)}" y2="180" stroke="#5b7880" stroke-dasharray="4 3"/><circle cx="${x(n)}" cy="${y(b.achieved_banking_confidence)}" r="5" fill="#b48e58"/><text x="${Math.min(650,x(n)+10)}" y="${Math.max(20,y(b.achieved_banking_confidence)-12)}" class="chart-value">${n} MII</text>`}${[0,.25,.5,.75,1].map(q=>`<text x="${x(Math.round(max*q))}" y="205" text-anchor="middle">${Math.round(max*q)}</text><text x="40" y="${y(q)+4}" text-anchor="end">${Math.round(q*100)}%</text>`).join('')}<text x="390" y="232" text-anchor="middle">MII</text></svg><div class="metric-row"><span>${t('euploid_required')}</span><strong>${b.euploid_needed}</strong></div><div class="metric-row"><span>${t('mii_required')}</span><strong>${n??t('banklimit')}</strong></div>`}
let bankSequence=0;
function bindBanking(){let timer;const run=()=>{clearTimeout(timer);$('#preg-target-label').value=$('#preg-target').value+'%';$('#bank-confidence-label').value=$('#bank-confidence').value+'%';timer=setTimeout(()=>guard(async()=>{const seq=++bankSequence,id=result.id,b=await api('banking_plan',{id,target:Number($('#preg-target').value)/100,confidence:Number($('#bank-confidence').value)/100});if(seq===bankSequence&&result.id===id){result.banking_plan=b;if($('#banking-output'))$('#banking-output').innerHTML=bankingHTML(b)}}),200)};$('#preg-target').oninput=$('#bank-confidence').oninput=run;if(!result.banking_plan)run()}
function stimulationHTML(r){if(!r.briefing)return `<p class="hint">${lang==='ru'?'Обновите ориентиры для единого краткого вывода.':'Refresh guidance for a combined concise summary.'}</p>`;
 return `<p>${esc(r.briefing[lang])}</p>${r.marker_discordance?`<p class="note">${t('reserve_discordance')}</p>`:''}<p class="hint">${esc(r.delta_note[lang])}</p><p class="hint">${esc(r.guidance_note[lang])}</p><details><summary>${t('evidencetitle')}</summary>${r.sources.map(v=>`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">${esc(v.source)}</a>`).join(' · ')}</details>`}
function stimulationPanel(r){return `<section class="panel"><h2>${t('stim')}</h2><div id="stim-output">${r.stimulation?stimulationHTML(r.stimulation):`<p class="hint">${lang==='ru'?'Краткие ориентиры по овариальному резерву и параметрам пациентки.':'Concise guidance based on ovarian reserve and patient parameters.'}</p>`}</div><button class="btn" id="stim">${t('stimrun')}</button></section>`}

Object.assign(text.ru,{gatgraph:'Граф клинических соседей',gatbars:'Вероятности ближайших соседей',gatprob:'Вероятность беременности · GAT',gatensemble:'Ансамбль GAT + KAT',gatlegend:'Вероятность GAT',gatpatient:'Пациентка',gatneighbour:'Сосед',similarity:'сходство',gataxis:'Вероятность беременности по GAT, %',graphnote:'Слева — все циклы обучающей выборки в двумерной проекции PCA с центром в положении пациентки; цвет точки — вероятность GAT, линии ведут к ближайшим соседям, толщина линии и размер узла отражают сходство. Справа — вероятности этих соседей: подпись строки — номер соседа и сходство, пунктир — пациентка, точечная линия — медиана соседей. Расстояния на плоскости не заменяют OOD-проверку.'});
Object.assign(text.en,{gatgraph:'Clinical neighbour graph',gatbars:'Nearest-neighbour probabilities',gatprob:'Pregnancy probability · GAT',gatensemble:'GAT + KAT ensemble',gatlegend:'GAT probability',gatpatient:'Patient',gatneighbour:'Neighbour',similarity:'similarity',gataxis:'GAT pregnancy probability, %',graphnote:'Left: all training cycles in a two-dimensional PCA projection centred on the patient; point colour shows the GAT probability, lines lead to the nearest neighbours, and line width and node size reflect similarity. Right: probabilities of those neighbours; each row shows the neighbour number and similarity, the dashed line marks the patient and the dotted line the neighbour median. Projected distances do not replace OOD assessment.'});
// GAT probability scale of the original Digital Twin figure (red up to 35%, amber at 45%, green from 55%), muted; mirrored in desktop/report_visuals.py.
const GAT_SCALE=[[0,[201,130,130]],[.35,[201,130,130]],[.45,[221,187,114]],[.55,[141,186,141]],[1,[141,186,141]]];
function gatColor(p){p=p==null||!Number.isFinite(+p)?.5:Math.max(0,Math.min(1,+p));let i=1;while(i<GAT_SCALE.length-1&&p>GAT_SCALE[i][0])i++;const [a,ca]=GAT_SCALE[i-1],[b,cb]=GAT_SCALE[i],u=b>a?(p-a)/(b-a):0;return ca.map((v,k)=>Math.round(v+(cb[k]-v)*u))}
const rgba=(c,a)=>`rgba(${c.join(',')},${a})`,deep=c=>c.map(v=>Math.round(v*.62));
function graphPanel(r){const g=r.technical?.gnn||{},n=g.neighbors;if(!n?.all_coords)return `<section class="panel"><p>${t('graphmissing')}</p></section>`;
 return `<section class="panel"><div class="graph-header"><h2>${t('cohortgraph')} · GAT</h2><span class="hint">${n.all_coords.length.toLocaleString(lang)} ${lang==='ru'?'циклов':'cycles'}</span><button class="btn" id="graph-reset">${t('resetview')}</button></div><div class="metric-row"><span>${t('gatprob')}</span><strong>${pct(g.gnn_prob)}</strong></div>${g.ensemble_prob==null?'':`<div class="metric-row"><span>${t('gatensemble')}</span><strong>${pct(g.ensemble_prob)}</strong></div>`}<div class="gat-layout"><div><h3>${t('gatgraph')}</h3><div class="graph-container"><canvas id="cohort-canvas" aria-label="${t('cohortgraph')}"></canvas><div id="graph-tooltip" class="graph-tooltip" hidden></div></div><div class="gat-legend"><span>${t('gatlegend')}:</span>${[[.2,'≤ 35%'],[.45,'35–55%'],[.8,'≥ 55%']].map(([v,s])=>`<span><i style="background:${rgba(gatColor(v),.9)}"></i>${s}</span>`).join('')}<span><b style="color:${rgba(gatColor(g.gnn_prob),1)}">★</b> ${t('gatpatient')}</span></div></div><div><h3>${t('gatbars')}</h3>${gatBars(g)}</div></div><p class="hint">${t('graphnote')}</p></section>`}
function gatBars(g){const n=g.neighbors,sims=(n.sims||[]).map(Number),rows=(n.indices||[]).map((id,i)=>({v:+(n.probs?.[i]??n.all_probs?.[id]),s:sims[i],i})).filter(d=>Number.isFinite(d.v)).sort((a,b)=>b.v-a.v);if(!rows.length)return '';
 const p=g.gnn_prob==null||!Number.isFinite(+g.gnn_prob)?null:+g.gnn_prob,W=460,top=42,rowH=30,base=top+rows.length*rowH,H=base+62,left=96,right=W-58;
 const xmax=Math.min(1,Math.max(p??0,...rows.map(d=>d.v))*1.2+.05),x=v=>left+v/xmax*(right-left),step=xmax>.6?.2:.1,ticks=[];for(let v=0;v<=xmax+1e-9;v+=step)ticks.push(v);
 const sorted=rows.map(d=>d.v).sort((a,b)=>a-b),m=sorted.length,med=m%2?sorted[(m-1)/2]:(sorted[m/2-1]+sorted[m/2])/2,pc=rgba(deep(gatColor(p)),1);
 const label=(v,y,s,color)=>{const half=s.length*3.3+4;return `<text x="${Math.max(half,Math.min(W-half,x(v)))}" y="${y}" text-anchor="middle" class="chart-halo"${color?` style="fill:${color}"`:''}>${esc(s)}</text>`};
 return `<svg class="gat-bars" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(t('gatbars'))}"><defs><pattern id="gat-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="6" stroke="rgba(75,92,105,.3)" stroke-width="1.2"/></pattern></defs>${ticks.map(v=>`<line x1="${x(v)}" x2="${x(v)}" y1="${top-6}" y2="${base}" class="chart-grid"/><text x="${x(v)}" y="${base+36}" text-anchor="middle">${Math.round(v*100)}</text>`).join('')}<line x1="${left}" x2="${left}" y1="${top-6}" y2="${base}" class="chart-axis"/><line x1="${x(med)}" x2="${x(med)}" y1="${top-6}" y2="${base}" stroke="#8a969c" stroke-dasharray="2 3"/>${p==null?'':`<line x1="${x(p)}" x2="${x(p)}" y1="${top-10}" y2="${base}" stroke="${pc}" stroke-width="1.6" stroke-dasharray="5 4"/>`}${rows.map((d,j)=>{const y=top+j*rowH,c=gatColor(d.v),w=Math.max(0,x(d.v)-left);return `<g><title>${esc(t('gatneighbour'))} #${d.i+1} · GAT ${pct(d.v)}</title><text x="${left-10}" y="${y+rowH/2}" text-anchor="end" dominant-baseline="middle">#${d.i+1} · ${Number.isFinite(d.s)?d.s.toFixed(2):'—'}</text><rect x="${left}" y="${y+5}" width="${w}" height="${rowH-10}" rx="2" fill="${rgba(c,.5)}"/><rect x="${left}" y="${y+5}" width="${w}" height="${rowH-10}" rx="2" fill="url(#gat-hatch)" stroke="${rgba(c,.95)}"/><text x="${x(d.v)+6}" y="${y+rowH/2}" dominant-baseline="middle" class="chart-value">${pct(d.v)}</text></g>`}).join('')}${label(med,base+17,t('median')+' '+pct(med))}${p==null?'':label(p,top-16,t('gatpatient')+' '+pct(p),pc)}<text x="${(left+right)/2}" y="${H-4}" text-anchor="middle">${esc(t('gataxis'))}</text></svg>`}
let graphRedraw=null;addEventListener('resize',()=>graphRedraw?.());
function drawPatientGraph(r){graphRedraw=null;const canvas=$('#cohort-canvas');if(!canvas)return;
 const g=r.technical.gnn,n=g.neighbors,ctx=canvas.getContext('2d'),pts=n.all_coords,raw=n.pat_coord[0],prob=n.all_probs||[],count=pts.length;
 // Same frame as the original figure: axes scaled to [-0.95, 0.95], centred on the patient, ±0.87 visible.
 let sx=1e-9,sy=1e-9;for(const q of pts){sx=Math.max(sx,Math.abs(q[0]));sy=Math.max(sy,Math.abs(q[1]))}
 const X=new Float32Array(count),Y=new Float32Array(count),bins=Array.from({length:101},()=>[]),px0=raw[0]/sx*.95,py0=raw[1]/sy*.95;
 for(let i=0;i<count;i++){X[i]=pts[i][0]/sx*.95-px0;Y[i]=pts[i][1]/sy*.95-py0;const v=prob[i];bins[v==null||!Number.isFinite(+v)?50:Math.round(Math.max(0,Math.min(1,+v))*100)].push(i)}
 const fills=bins.map((_,b)=>rgba(gatColor(b/100),.5)),ids=(n.indices||[]).map(Number),sims=(n.sims||[]).map(Number),smin=Math.min(...sims),smax=Math.max(...sims),simN=i=>smax>smin?(sims[i]-smin)/(smax-smin):1,nprob=i=>n.probs?.[i]??prob[ids[i]],valid=id=>id>=0&&id<count,pColor=gatColor(g.gnn_prob),font='"Segoe UI",Arial,sans-serif';
 let zoom=1,dx=0,dy=0,drag=null,W=0,H=0,frame=0;const scale=()=>zoom*Math.min(W,H)/2/.87;
 function draw(){const w=canvas.clientWidth,h=canvas.clientHeight,dpr=devicePixelRatio||1;if(!w||!h)return;if(w!==W||h!==H||canvas.width!==Math.round(w*dpr)){W=w;H=h;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);
  const s=scale(),ox=W/2+dx,oy=H/2+dy,rad=Math.min(3.2,1.5*Math.sqrt(zoom));
  // One path per colour bin keeps 16k points to ~100 fill calls.
  for(let b=0;b<101;b++){const list=bins[b];if(!list.length)continue;ctx.fillStyle=fills[b];ctx.beginPath();for(const i of list){const x=ox+X[i]*s,y=oy-Y[i]*s;if(x<-4||y<-4||x>W+4||y>H+4)continue;ctx.moveTo(x+rad,y);ctx.arc(x,y,rad,0,6.2832)}ctx.fill()}
  ctx.lineCap='round';ctx.strokeStyle='rgba(113,128,140,.45)';ids.forEach((id,i)=>{if(!valid(id))return;ctx.lineWidth=.6+1.2*simN(i);ctx.beginPath();ctx.moveTo(ox,oy);ctx.lineTo(ox+X[id]*s,oy-Y[id]*s);ctx.stroke()});
  ctx.font='11px '+font;ctx.textAlign='center';ctx.textBaseline='middle';
  ids.forEach((id,i)=>{if(!valid(id))return;const x=ox+X[id]*s,y=oy-Y[id]*s,pv=nprob(i),c=gatColor(pv),rr=4+3.5*simN(i);ctx.fillStyle=rgba(c,.95);ctx.strokeStyle='#fff';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,rr,0,6.2832);ctx.fill();ctx.stroke();
   const d=Math.hypot(x-ox,y-oy)||1,lx=x+(x-ox)/d*(rr+14),ly=y+(y-oy)/d*(rr+14),label=pv==null?'—':Math.round(pv*100)+'%',tw=ctx.measureText(label).width;ctx.fillStyle='rgba(255,254,250,.8)';ctx.fillRect(lx-tw/2-3,ly-8,tw+6,16);ctx.fillStyle=rgba(deep(c),1);ctx.fillText(label,lx,ly)});
  ctx.beginPath();for(let k=0;k<10;k++){const a=-Math.PI/2+k*Math.PI/5,rr=k%2?4.8:11;ctx.lineTo(ox+Math.cos(a)*rr,oy+Math.sin(a)*rr)}ctx.closePath();ctx.fillStyle=rgba(pColor,1);ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.lineJoin='round';ctx.fill();ctx.stroke();
  const tag=t('gatpatient')+(g.gnn_prob==null?'':' '+pct(g.gnn_prob));ctx.font='600 12px '+font;const tw=ctx.measureText(tag).width,ty=oy-27;ctx.fillStyle='rgba(255,254,250,.92)';ctx.strokeStyle=rgba(pColor,1);ctx.lineWidth=1;ctx.beginPath();ctx.rect(ox-tw/2-7,ty-10,tw+14,20);ctx.fill();ctx.stroke();ctx.fillStyle=rgba(deep(pColor),1);ctx.fillText(tag,ox,ty)}
 const request=()=>{if(!frame)frame=requestAnimationFrame(()=>{frame=0;draw()})};
 canvas.onwheel=e=>{e.preventDefault();const z=Math.max(.6,Math.min(15,zoom*(e.deltaY>0?.9:1.1))),k=z/zoom,cx=e.offsetX-W/2,cy=e.offsetY-H/2;dx=cx-(cx-dx)*k;dy=cy-(cy-dy)*k;zoom=z;request()};
 canvas.onpointerdown=e=>{drag=[e.offsetX,e.offsetY];canvas.setPointerCapture(e.pointerId);canvas.style.cursor='grabbing'};canvas.onpointerup=canvas.onpointercancel=()=>{drag=null;canvas.style.cursor=''};canvas.onpointerleave=()=>{$('#graph-tooltip').hidden=true};
 canvas.onpointermove=e=>{const tip=$('#graph-tooltip');if(drag){dx+=e.offsetX-drag[0];dy+=e.offsetY-drag[1];drag=[e.offsetX,e.offsetY];tip.hidden=true;request();return}
  const s=scale(),ox=W/2+dx,oy=H/2+dy,ex=e.offsetX,ey=e.offsetY;let label='',best=100,hit=-1;
  if((ex-ox)**2+(ey-oy)**2<144)label=t('gatpatient')+' · GAT '+pct(g.gnn_prob);
  else{ids.forEach((id,i)=>{if(!valid(id))return;const d=(ox+X[id]*s-ex)**2+(oy-Y[id]*s-ey)**2;if(d<best){best=d;hit=i}});
   if(hit>=0)label=`${t('gatneighbour')} #${hit+1} · GAT ${pct(nprob(hit))} · ${t('similarity')} ${Number.isFinite(sims[hit])?sims[hit].toFixed(2):'—'}`;
   else{best=49;for(let i=0;i<count;i++){const d=(ox+X[i]*s-ex)**2+(oy-Y[i]*s-ey)**2;if(d<best){best=d;hit=i}}if(hit>=0)label=t('cohortnode')+' '+(hit+1)+' · GAT '+pct(prob[hit])}}
  tip.hidden=!label;if(label){tip.textContent=label;tip.style.left=Math.max(0,Math.min(W-280,ex+14))+'px';tip.style.top=Math.max(0,ey-34)+'px'}};
 $('#graph-reset').onclick=()=>{zoom=1;dx=dy=0;request()};graphRedraw=request;draw();
}


let reliabilityConfig={moderate:45,high:70};
Object.assign(text.ru,{calibration_title:'Калибровка прогноза для клиники',calibration_help:'CSV в UTF-8: одна строка на перенос, patient_id — постоянный обезличенный код пациентки, record_id — уникальный код записи. Исход clinical_pregnancy_ultrasound: 1 — беременность подтверждена УЗИ, 0 — нет, пусто — исход неизвестен. transfer_performed: 1 или 0. Для uncalibrated_probability используйте исходный прогноз этой версии без калибровки центра. Вместо вероятности можно передать age, amh, afc, bmi и известные этапы на момент прогноза.',calibration_confirm:'Подтверждаю: исход — клиническая беременность по УЗИ; прогнозы получены до установления исхода, без калибровки центра.',calibration_run:'Проверить и откалибровать',calibration_disable:'Отключить калибровку',calibration_active:'Калибровка включена для новых расчётов',calibration_inactive:'Калибровка не включена',calibration_rejected:'Новая калибровка не улучшила оба показателя на проверочной выборке и не применена.',calibration_note:'Не менее 100 переносов и 60 пациенток; в каждой части выборки нужны оба исхода (не менее 10 каждого). Четверть пациенток отделяется для проверки. Коррекция включается автоматически только при улучшении оценки Брайера и логарифмической потери. Это проверка на части данных, а не подтверждение клинической валидности. Корректируются итоговая вероятность при переносе, её интервал и распределение сценариев; отдельные слои и формула банкинга сохраняются. Интервал не включает неопределённость параметра калибровки.',calibration_csv:'Проверьте формат CSV, уникальность записей, значения исходов и вероятностей.',calibration_small:'Недостаточно пациенток или одного из исходов в обучающей либо проверочной части.',calibration_target:'Подтвердите определение исхода и происхождение прогнозов.',calibration_too_many:'Для расчёта исходных прогнозов допускается до 500 строк. Для готовых вероятностей — до 5000.',calibration_corrupt:'Файл калибровки повреждён. Восстановите сохранённую копию настроек.',calibration_failed:'Не удалось оценить параметр калибровки.',holdout:'Проверочные переносы',before:'До',after:'После',brier:'Оценка Брайера',logloss:'Логарифмическая потеря',center_adjusted:'Применена калибровка клиники. Неопределённость её параметра в диапазон не включена.'});
Object.assign(text.en,{calibration_title:'Clinic forecast calibration',calibration_help:'UTF-8 CSV: one row per transfer, patient_id is a stable pseudonymous patient code; record_id is unique. clinical_pregnancy_ultrasound: 1 for ultrasound-confirmed pregnancy, 0 for no pregnancy, blank for unknown. transfer_performed: 1 or 0. uncalibrated_probability must be this version’s original forecast without clinic calibration. Alternatively provide age, amh, afc, bmi and stages known at prediction time.',calibration_confirm:'I confirm ultrasound-confirmed clinical pregnancy as the outcome, with predictions made before outcome ascertainment and without clinic calibration.',calibration_run:'Check and calibrate',calibration_disable:'Disable calibration',calibration_active:'Calibration enabled for new calculations',calibration_inactive:'Calibration is not enabled',calibration_rejected:'The new calibration did not improve both holdout metrics and was not applied.',calibration_note:'At least 100 transfers and 60 patients; both split subsets need at least 10 of each outcome. One quarter of patients are held out. Correction activates only if Brier score and log loss improve. This is a holdout check, not clinical validation. It adjusts the final per-transfer probability, its interval and scenario distribution; individual layers and the banking equation remain unchanged. The interval excludes calibration-parameter uncertainty.',calibration_csv:'Check CSV format, unique records, outcomes and probabilities.',calibration_small:'Insufficient patients or outcome classes in the fitting or holdout subset.',calibration_target:'Confirm the outcome definition and prediction provenance.',calibration_too_many:'Up to 500 rows when computing original forecasts, or 5000 with precomputed probabilities.',calibration_corrupt:'The calibration file is damaged. Restore a saved settings copy.',calibration_failed:'Calibration fitting failed.',holdout:'Holdout transfers',before:'Before',after:'After',brier:'Brier score',logloss:'Log loss',center_adjusted:'Clinic calibration applied. The range excludes uncertainty in its parameter.'});
let intakeReport=null;
function revisionSettings(){return `<section class="panel"><h2>${t('reliabilitysettings')}</h2><p class="hint">${t('reliabilityhelp')}</p><form id="reliability-form"><div class="grid2">${field('moderate',reliabilityConfig.moderate,0,99)}${field('high',reliabilityConfig.high,1,100)}</div><div class="actions"><button class="btn">${t('apply')}</button></div></form></section><section class="panel"><h2>${t('calibration_title')}</h2><p>${t('calibration_help')}</p><form id="calibration-form"><div class="actions"><label class="btn">${t('csvfile')}<input type="file" id="calibration-file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden></label><button class="btn" type="button" id="calibration-template">${t('csvtemplate')}</button><button class="btn" type="button" id="calibration-template-xlsx">${t('xlsxtemplate')}</button><button class="btn" type="button" id="calibration-requirements">${t('data_requirements')}</button></div><label class="field table-preview">${t('table_preview')}<textarea id="calibration-content" rows="6" wrap="off" spellcheck="false" required></textarea></label><div class="actions"><button class="btn" type="button" id="calibration-validate">${t('validate_csv')}</button></div><div id="calibration-validation"></div><label class="settings-check"><span><input type="checkbox" id="calibration-confirm" required> ${t('calibration_confirm')}</span></label><div class="actions"><button class="btn primary" id="calibration-start" disabled>${t('calibration_run')}</button><button class="btn" type="button" id="calibration-disable">${t('calibration_disable')}</button></div></form><div id="calibration-status"></div><div id="calibration-history"></div><p class="hint">${t('calibration_note')}</p></section>${labPanel()}`}
function calibrationStatus(v){return `<p>${t(v.stale?'calibration_stale':v.enabled?'calibration_active':'calibration_inactive')}</p>${v.decision?`<p>${t('decision_'+v.decision)}</p>`:''}${v.intercept_ci95?`<p>${t('cal_intercept')}: ${v.intercept.toFixed(3)} [${v.intercept_ci95.map(x=>x.toFixed(3)).join('; ')}]</p><p>${t('cal_slope')}: ${v.slope.toFixed(3)} [${v.slope_ci95.map(x=>x.toFixed(3)).join('; ')}]</p><p>${t('brier')}: ${v.brier_before.toFixed(4)} → ${v.brier_after.toFixed(4)} · ${t('fitting_data')}</p>`:''}`}
function validationHTML(v,kind='transfers'){const z=v.summary||{};return `<p>${t(kind==='lab'?'included_cycles':'included_rows')}: ${z.included??0}${kind==='lab'?'':` · ${t('patients')}: ${z.patients??0} · ${t('pregnancies')}: ${z.pregnancies??0} / ${z.non_pregnancies??0}`}</p>${v.blocking.length?`<p class="note">${v.blocking.map(k=>esc(t('intake_'+k))).join('; ')}</p>`:''}${v.issues.length?`<details><summary>${t('row_issues')} (${v.issues.length})</summary><table class="data-table"><thead><tr><th>${t('row')}</th><th>${t('column')}</th><th>${t('reason')}</th></tr></thead><tbody>${v.issues.map(v=>`<tr><td>${v.row}</td><td>${esc(v.column)}</td><td>${esc(t('intake_'+v.code))}</td></tr>`).join('')}</tbody></table></details>`:''}${Object.keys(v.excluded||{}).length?`<p>${Object.entries(v.excluded).filter(([k,n])=>n).map(([k,n])=>esc(t('intake_'+k))+': '+n).join(' · ')}</p>`:''}${v.warnings.map(v=>`<label class="field"><span><input type="checkbox" data-cal-warning="${esc(v.code)}"> ${esc(t('intake_'+v.code))}</span></label>`).join('')}`}
function bindRevisionSettings(){if(!$('#reliability-form'))return;intakeReport=null;bindLab();
 guard(async()=>{reliabilityConfig=await api('reliability_settings');if($('#reliability-form'))for(const k of ['moderate','high'])$('#reliability-form').elements[k].value=reliabilityConfig[k];const v=await api('center_calibration');if($('#calibration-status'))$('#calibration-status').innerHTML=calibrationStatus(v);const rows=await api('calibration_history');if($('#calibration-history')){$('#calibration-history').innerHTML=rows.map(v=>`<p>${esc(v.created.slice(0,16))} · ${t('decision_'+v.decision)} ${v.decision==='activate'?`<button type="button" class="btn" data-cal-restore="${esc(v.name)}">${t('restore')}</button>`:''}</p>`).join('');for(const btn of document.querySelectorAll('[data-cal-restore]'))btn.onclick=()=>guard(async()=>{$('#calibration-status').innerHTML=calibrationStatus(await api('calibration_restore',{name:btn.dataset.calRestore}))})}});
 $('#reliability-form').onsubmit=e=>{e.preventDefault();guard(async()=>{reliabilityConfig=await api('reliability_settings',{...readForm(e.target),save:true});toast(t('thresholdsaved'))})};
 const invalidate=()=>{intakeReport=null;$('#calibration-start').disabled=true;$('#calibration-validation').innerHTML=''};$('#calibration-content').oninput=invalidate;
 $('#calibration-file').onchange=()=>guard(async()=>{const file=$('#calibration-file').files[0];if(!file)return;$('#calibration-content').value='';invalidate();const out=await readClinicFile(file,'transfers');$('#calibration-content').value=out.csv;invalidate();toast(t('table_loaded')+': '+out.rows)});
 const template=(kind,format='csv')=>guard(()=>downloadTemplate(kind,format));
 $('#calibration-template').onclick=()=>template('transfers');$('#calibration-template-xlsx').onclick=()=>template('transfers','xlsx');$('#calibration-requirements').onclick=()=>template('requirements');
 const enable=()=>{$('#calibration-start').disabled=!intakeReport||intakeReport.blocking.length>0||[...document.querySelectorAll('[data-cal-warning]')].some(el=>!el.checked)||!$('#calibration-confirm').checked};
 $('#calibration-confirm').onchange=enable;
 $('#calibration-validate').onclick=()=>guard(async()=>{intakeReport=await api('calibration_validate',{csv:$('#calibration-content').value});$('#calibration-validation').innerHTML=validationHTML(intakeReport);for(const el of document.querySelectorAll('[data-cal-warning]'))el.onchange=enable;enable()});
 $('#calibration-disable').onclick=()=>guard(async()=>{$('#calibration-status').innerHTML=calibrationStatus(await api('center_calibration',{disable:true}))});
 $('#calibration-form').onsubmit=e=>{e.preventDefault();guard(async()=>{const v=await job('calibrate_csv',{csv:$('#calibration-content').value,sha256:intakeReport.sha256,acknowledged_warnings:intakeReport.warnings.map(v=>v.code),target_confirmed:$('#calibration-confirm').checked});$('#calibration-status').innerHTML=calibrationStatus(v);$('#calibration-content').value='';invalidate()})};
}
Object.assign(text.ru,{calibration_help:'Загрузите файл переносов по шаблону. Приложение сначала проверит строки, затем само рассчитает исходные прогнозы перед переносом. Пустые обязательные параметры не заменяются средними значениями.',calibration_confirm:'Исход — клиническая беременность по УЗИ, включая подтверждённую внематочную. Данные соответствуют моменту перед переносом; замечания к файлу проверены.',calibration_note:'Требуется не менее 100 беременностей, 100 переносов без беременности и 100 пациенток. Интервал поправки учитывает повторные переносы одной пациентки. Включение зависит от интервала, размера сдвига и наклона калибровки. При изменении моделей поправка отключается. Применяется только перед переносом; неопределённость её параметра не включена в интервал прогноза.',validate_csv:'Проверить файл',data_requirements:'Требования к данным',included_rows:'Включено переносов',patients:'Пациенток',pregnancies:'Беременность / нет беременности',row_issues:'Замечания по строкам',row:'Строка',column:'Столбец',reason:'Причина',restore:'Восстановить',cal_intercept:'Поправка логарифма шансов и 95% интервал',cal_slope:'Наклон и 95% интервал',fitting_data:'на данных подгонки',decision_activate:'Поправка включена',decision_no_change:'Поправка не требуется по критерию включения',decision_review_slope:'Требуется разбор: изменение наклона не исправляется одной поправкой',decision_review_large_shift:'Требуется разбор: слишком большой сдвиг',decision_insufficient_data:'Недостаточно данных',calibration_stale:'Поправка отключена: модель или статистика клиники изменились',center_not_applicable:'Калибровка клиники относится к прогнозу перед переносом; к этому расчёту она не применена.',calibration_revalidate:'Файл или замечания изменились. Повторите проверку.',calibration_compute_errors:'Не удалось рассчитать более 1% переносов; калибровка не изменена.',cancel:'Отменить',cancelled:'Расчёт отменён. Калибровка не изменена.'});
Object.assign(text.en,{calibration_help:'Upload transfers using the template. The application first validates rows, then computes original pre-transfer forecasts. Missing required parameters are never imputed.',calibration_confirm:'The outcome is ultrasound-confirmed clinical pregnancy, including confirmed ectopic pregnancy. Data reflect the pre-transfer timepoint; file warnings have been checked.',calibration_note:'At least 100 pregnancies, 100 non-pregnancies and 100 patients. The intercept interval accounts for repeated transfers per patient. Activation considers the interval, effect size and calibration slope. Changing models disables the correction. Applies only before transfer; parameter uncertainty is not included in the forecast interval.',validate_csv:'Validate file',data_requirements:'Data requirements',included_rows:'Included transfers',patients:'Patients',pregnancies:'Pregnancy / no pregnancy',row_issues:'Row issues',row:'Row',column:'Column',reason:'Reason',restore:'Restore',cal_intercept:'Log-odds adjustment and 95% interval',cal_slope:'Slope and 95% interval',fitting_data:'on fitting data',decision_activate:'Correction activated',decision_no_change:'No correction indicated by the activation rule',decision_review_slope:'Review required: an intercept cannot correct a slope shift',decision_review_large_shift:'Review required: large shift',decision_insufficient_data:'Insufficient data',calibration_stale:'Correction disabled: model or clinic statistics changed',center_not_applicable:'Clinic calibration is for pre-transfer forecasts and was not applied here.',calibration_revalidate:'File or warnings changed. Validate again.',calibration_compute_errors:'More than 1% of forecasts failed; calibration unchanged.',cancel:'Cancel',cancelled:'Calculation cancelled. Calibration unchanged.'});
