Object.assign(text.ru,{gonadotropin:'Группа гонадотропина',agent_fsh:'ФСГ: рекомбинантный (фоллитропин альфа/бета) или высокоочищенный',agent_hmg:'Менотропины (чМГ)',agent_delta:'Фоллитропин дельта — отдельная номограмма',guidance_updated:'Ориентиры стимуляции рассчитаны',cluster_0:'Обычный ответ',cluster_1:'Сниженный ответ',cluster_2:'Высокий ответ (гиперответ)',clusternote:'Это группы модели по сходству сценариев овариального ответа. POSEIDON отдельно классифицирует сниженный прогноз по возрасту, резерву и фактическому ответу на предшествующую стимуляцию; номера этих кластеров не являются группами POSEIDON.',betanote:'Образование бластоцист: бета-биномиальная модель с дополнительной вероятностью нулевого выхода; качество: бета-биномиальная модель. Параметры уточнены по локальной когорте 10.09.2026.',csdi_excluded:'CSDI вне области применимости — не участвует в объединённой оценке.',csdi_unchecked:'Область применимости CSDI не проверена — CSDI не участвует в объединённой оценке.'});
Object.assign(text.en,{gonadotropin:'Gonadotropin class',agent_fsh:'FSH: recombinant (follitropin alfa/beta) or highly purified',agent_hmg:'Menotropins (hMG)',agent_delta:'Follitropin delta — separate nomogram',guidance_updated:'Stimulation guidance calculated',cluster_0:'Standard response',cluster_1:'Reduced response',cluster_2:'High response',clusternote:'Model groups reflect similarity of ovarian-response scenarios. POSEIDON separately classifies low prognosis by age, reserve and observed response to previous stimulation; these cluster numbers are not POSEIDON groups.',betanote:'Blastocyst formation uses a zero-inflated beta-binomial model; quality uses a beta-binomial model. Parameters were refitted on the local cohort on 10 September 2026.',csdi_excluded:'CSDI is outside its applicability domain and is excluded from the combined estimate.',csdi_unchecked:'CSDI applicability has not been assessed, so CSDI is excluded from the combined estimate.'});
Object.assign(text.ru,{iu_day:'МЕ/сут',starting_range:'Ориентир стартовой дозы',nomogram_dose:'Суточная доза по номограмме',expected_response:'Ожидаемый ответ',normal_responder:'Обычный',poor_responder:'Сниженный',high_responder:'Высокий',range_help:'Диапазон активности ФСГ выбран по ожидаемому ответу. Для фоллитропина альфа/бета и менотропинов он может совпадать. Изменение массы тела само по себе не задаёт прибавку в МЕ; окончательная доза зависит также от предыдущей стимуляции и инструкции препарата.',previous_delta_dose:'Предыдущая доза, мкг/сут',previous_response:'Ответ в предыдущем цикле',choose_response:'Выберите наблюдавшийся ответ',response_adequate:'Достаточный, без СГЯ — прежняя доза',response_low25:'Сниженный — увеличение на 25%',response_low50:'Сниженный — увеличение на 50%',response_high20:'Избыточный — снижение на 20%',response_high33:'Избыточный — снижение на 33%',response_ohss:'СГЯ или его риск — снижение на 33%',delta_repeat_help:'Степень коррекции при сниженном или избыточном ответе выбирает врач по результатам прошлого цикла. Доза округляется по шкале ручки; максимум 24 мкг/сут.',delta_previous_missing:'Укажите предыдущую дозу фоллитропина дельта и наблюдавшийся ответ.',reserve_discordance:'АМГ и КАФ дают противоречивую оценку резерва. Автоматический ориентир отдаёт приоритет профилактике СГЯ; проверьте показатели и прошлый ответ.'});
Object.assign(text.en,{iu_day:'IU/day',starting_range:'Starting-dose range',nomogram_dose:'Daily nomogram dose',expected_response:'Expected response',normal_responder:'Normal',poor_responder:'Low',high_responder:'High',range_help:'The FSH activity range reflects expected response. Follitropin alfa/beta and menotropins may share this range. Weight alone does not determine an IU increment; the final dose also depends on previous stimulation and product information.',previous_delta_dose:'Previous dose, micrograms/day',previous_response:'Previous cycle response',choose_response:'Select observed response',response_adequate:'Adequate, no OHSS — same dose',response_low25:'Low — increase by 25%',response_low50:'Low — increase by 50%',response_high20:'High — reduce by 20%',response_high33:'High — reduce by 33%',response_ohss:'OHSS or OHSS risk — reduce by 33%',delta_repeat_help:'The clinician selects the adjustment for low or excessive response using the previous cycle. Rounded to the pen scale; maximum 24 micrograms/day.',delta_previous_missing:'Enter the previous follitropin delta dose and observed response.',reserve_discordance:'AMH and AFC give discordant reserve estimates. The automatic range prioritises OHSS prevention; review the markers and previous response.'});

function labPanel(){return `<section class="panel"><h2>${t('lab_title')}</h2><p>${t('lab_help')}</p><div class="actions"><label class="btn">${t('csvfile')}<input type="file" id="lab-file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" hidden></label><button class="btn" id="lab-template">${t('csvtemplate')}</button><button class="btn" id="lab-template-xlsx">${t('xlsxtemplate')}</button></div><label class="field table-preview" id="lab-preview" hidden>${t('table_preview_readonly')}<textarea id="lab-content" rows="6" wrap="off" spellcheck="false" readonly></textarea></label><div id="lab-output"></div></section>`}
function labHTML(v){if(!v)return '';if(v.validation)return validationHTML({...v.validation,warnings:[]},'lab');const ratio=z=>z?.ratio==null?'—':num(z.ratio)+' ['+(z.ci95||[]).map(num).join('; ')+']';const quant=a=>a?a.map(num).join(' / '):'—';return `<p>${t('included_cycles')}: ${v.summary.included} · ${esc(v.created.slice(0,10))}</p><table class="data-table"><tbody><tr><td>${t('lab_befe')}</td><td>${pct(v.befe_ood.fraction)}</td></tr><tr><td>${t('lab_csdi')}</td><td>${pct(v.csdi_ood.fraction)}</td></tr><tr><td>${t('lab_zero_blast')}</td><td>${ratio(v.zero_blasts)}</td></tr><tr><td>${t('lab_zero_good')}</td><td>${ratio(v.zero_good)}</td></tr></tbody></table>${[v.befe_ood,v.csdi_ood,v.zero_blasts,v.zero_good].some(z=>z.warning)?`<p class="note">${t('lab_shift')}</p>`:''}<p class="hint">${t('lab_proxy')}</p><details><summary>${t('lab_quantiles')}</summary><table class="data-table"><thead><tr><th></th><th>${t('lab_clinic')}</th><th>${t('lab_reference')}</th></tr></thead><tbody>${Object.entries(v.quantiles).map(([k,a])=>`<tr><td>${t('lab_'+k)}</td><td>${quant(a)}</td><td>${quant(v.reference?.quantiles?.[k])}</td></tr>`).join('')}</tbody></table></details>`}
function bindLab(){if(!$('#lab-file'))return;guard(async()=>{const v=await api('lab_compatibility_report',{status:true});if($('#lab-output'))$('#lab-output').innerHTML=labHTML(v)});$('#lab-template').onclick=()=>guard(()=>downloadTemplate('lab'));$('#lab-template-xlsx').onclick=()=>guard(()=>downloadTemplate('lab','xlsx'));$('#lab-file').onchange=()=>guard(async()=>{const file=$('#lab-file').files[0];if(!file)return;$('#lab-preview').hidden=true;$('#lab-content').value='';const out=await readClinicFile(file,'lab');$('#lab-content').value=out.csv;$('#lab-preview').hidden=false;const v=await job('lab_compatibility_report',{csv:out.csv});if($('#lab-output'))$('#lab-output').innerHTML=labHTML(v)})}
Object.assign(text.ru,{lab_title:'Совместимость лабораторных данных',lab_help:'Загрузите лабораторный файл CSV или Excel (.xlsx): не менее 300 циклов с наблюдаемым культивированием до бластоцисты и 2PN ≥ 1. Проверка сравнивает данные с заводскими моделями и сохраняет только сводный отчёт; прогнозы не изменяются.',lab_befe:'За пределами обучающей выборки объединённой модели',lab_csdi:'За пределами обучающей выборки диффузионной модели',lab_zero_blast:'Без бластоцист: наблюдаемое / ожидаемое, 95% интервал',lab_zero_good:'Без хороших бластоцист: наблюдаемое / ожидаемое, 95% интервал',lab_shift:'Обнаружено расхождение с обучающей выборкой или моделью нулевого выхода. Проверьте определения полей и особенности лаборатории.',lab_proxy:'Инсеминированные ооциты используются так же, как в обучающей выборке; при ЭКО они не равны MII. Оценка CSDI использует восстановленный KPIScore. Интервалы учитывают повторные циклы одной пациентки.',lab_quantiles:'25-й перцентиль / медиана / 75-й перцентиль',lab_clinic:'Клиника',lab_reference:'Референсная выборка',lab_okk:'ОКК',lab_pn2_per_okk:'2PN / ОКК',lab_blasts_per_pn2:'Бластоцисты / 2PN',lab_good_per_blast:'Хорошие / все бластоцисты'});
Object.assign(text.en,{lab_title:'Laboratory data compatibility',lab_help:'Upload a laboratory CSV or Excel (.xlsx) file with at least 300 culture-observed cycles and 2PN ≥ 1. This checks against factory models and saves only an aggregate report; forecasts are unchanged.',lab_befe:'Outside the combined model training cohort',lab_csdi:'Outside the diffusion model training cohort',lab_zero_blast:'Zero blastocysts: observed / expected, 95% interval',lab_zero_good:'Zero good blastocysts: observed / expected, 95% interval',lab_shift:'A training-cohort or zero-yield model discrepancy was detected. Review field definitions and laboratory characteristics.',lab_proxy:'Inseminated counts follow the training definition; in IVF they are not MII. CSDI assessment uses a reconstructed KPIScore. Intervals account for repeat cycles per patient.',lab_quantiles:'25th percentile / median / 75th percentile',lab_clinic:'Clinic',lab_reference:'Reference cohort',lab_okk:'Oocytes',lab_pn2_per_okk:'2PN / oocytes',lab_blasts_per_pn2:'Blastocysts / 2PN',lab_good_per_blast:'Good / all blastocysts'});
const moreIntake={outside_good_blast_model:['Нет хороших бластоцист (исключение прежних версий)','No good blastocysts (exclusion in earlier versions)'],insufficient_lab_cycles:['Нужно не менее 300 подходящих лабораторных циклов','At least 300 eligible laboratory cycles required'],cancelled_with_counts:['При отмене лабораторные поля должны быть пустыми','Cancelled cycle must have blank lab counts'],culture_not_observed:['Культивирование до бластоцист не наблюдалось','Blastocyst culture not observed'],known_without_outcome:['Для известного исхода нужно 0 или 1','Known outcome requires 0 or 1'],outcome_not_final:['Незавершённый исход должен быть пустым','Pending outcome must be blank'],transfer_without_blastocyst:['Перенос при отсутствии бластоцист','Transfer with no blastocysts'],pgt_without_result:['Нет результата ПГТ-А','PGT-A result missing'],euploid_without_pgt:['Эуплоидные без ПГТ-А','Euploid count without PGT-A'],pgt_transfer_without_euploid:['Перенос после ПГТ-А без эуплоидных','PGT-A transfer without euploid embryos'],cycle_inconsistent:['Данные одного цикла различаются','Inconsistent cycle data'],donor_oocytes:['Донорские ооциты','Donor oocytes'],multiple_embryo_transfer:['Перенос нескольких эмбрионов','Multiple embryo transfer'],not_blastocyst:['Перенос другой стадии','Other embryo stage'],pgt_a_transfer:['Перенос после ПГТ-А','PGT-A transfer'],outcome_pending:['Исход ожидается','Outcome pending'],outcome_lost:['Исход неизвестен','Outcome lost'],row_error:['Ошибки строк','Row errors'],cancelled_cycle:['Отменённый цикл','Cancelled cycle'],no_2pn:['Нет 2PN','No 2PN']};for(const [k,v] of Object.entries(moreIntake)){text.ru['intake_'+k]=v[0];text.en['intake_'+k]=v[1]}

Object.assign(text.ru,{interval:"95% интервал",clinicpriorhelp:"Число беременностей среди переносов используется в дополнительной байесовской оценке. Используйте одинаковое определение исхода для всех периодов.",calibration_too_many:"Не более 5 МБ и 20 000 строк; в подгонке используются последние 1000 подходящих переносов."});
