Object.assign(text.ru,{intake_invalid_forecast_provenance:'Происхождение готового прогноза не подтверждено: используйте экспорт этой версии под той же учётной записью Windows',calibration_help:'Загрузите файл переносов по шаблону. Сначала проверяются строки, затем рассчитываются исходные прогнозы. Можно повторно использовать CSV, полученный пакетным расчётом шаблона переносов на этом ПК: приложение проверит модель и целостность каждой строки.',batchhelp:'CSV в UTF-8, до 200 строк. Для обычного расчёта обязательны age, amh, afc, bmi; можно добавить patient_id, attempt, n_sim и известные этапы known_*. Для экспорта прогнозов калибровки загрузите полный шаблон переносов с известными исходами; результат можно вернуть в модуль калибровки без повторного расчёта моделей.'});
Object.assign(text.en,{intake_invalid_forecast_provenance:'Forecast provenance could not be verified: use this version’s export under the same Windows account',calibration_help:'Upload transfers using the template. Rows are validated before original forecasts are computed. A CSV exported by batch scoring the transfer template on this PC can be reused; the application verifies the model and each row’s integrity.',batchhelp:'UTF-8 CSV, up to 200 rows. Standard batches require age, amh, afc, bmi; patient_id, attempt, n_sim and known_* stages are optional. To export calibration forecasts, upload the full transfer template with known outcomes. Its output can be returned to calibration without rescoring models.'});

text.ru.intake_unsafe_identifier="Код должен быть коротким и не начинаться со знака формулы";text.en.intake_unsafe_identifier="Use a short code that does not start with a formula marker";

async function readClinicFile(file,kind){if(file.size>5*1024*1024)throw Error('table_too_large');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return api('read_table',{filename:file.name,content:btoa(binary),kind})}
async function downloadTemplate(kind,format='csv'){const out=await api('clinic_template',{kind,format,language:lang});downloadText(Uint8Array.from(atob(out.content),c=>c.charCodeAt(0)),out.filename,out.mime)}
Object.assign(text.ru,{csvfile:'Загрузить CSV или Excel',csvtemplate:'Шаблон CSV',xlsxtemplate:'Шаблон Excel',output_format:'Формат результата',batchrun:'Рассчитать и скачать',table_loaded:'Загружено строк',table_empty:'Лист данных пуст. Заполните его строками циклов; примеры находятся на отдельном листе.',table_invalid:'Не удалось прочитать таблицу. Сохраните исправный файл Excel (.xlsx) или CSV UTF-8.',table_format:'Поддерживаются CSV и Excel .xlsx. Старый .xls сохраните как .xlsx.',table_encoding:'Сохраните CSV в кодировке UTF-8.',table_too_large:'Файл слишком велик: до 5 МБ, 200 циклов для пакетного расчёта или 20 000 строк для анализа клиники.',table_columns:'Заголовки или число колонок не соответствуют шаблону. Проверьте пропуски, повторения и лишние столбцы.',table_sheet:'Нужен один лист Data (Данные) с колонками шаблона. Уберите неоднозначность выбора листа.',table_formula:'В ячейке формула. Перед загрузкой замените формулы вычисленными значениями',table_cell_error:'Недопустимое значение или ошибка Excel в ячейке',table_date:'Дата допустима только в колонке месяца; проверьте ячейку',table_external:'Используйте обычный .xlsx без макросов и внешних ссылок.',batchhelp:'CSV UTF-8 или Excel (.xlsx), до 200 циклов. В шаблоне Excel заполните лист Data; отдельные примеры не участвуют в расчёте. Обязательны age, amh, afc, bmi; неизвестные этапы оставляйте пустыми. Результат можно скачать в обоих форматах.',calibration_help:'Загрузите переносы в CSV UTF-8 или Excel (.xlsx) по шаблону. Проверки и калибровка одинаковы для обоих форматов. Можно повторно использовать экспорт прогнозов пакетного расчёта этой версии: проверяются модель и целостность строк.'});
